import React, { useRef } from 'react'
import type { DefaultValues } from 'react-hook-form'
import { Controller, FormProvider, useFormContext } from 'react-hook-form'
import Button from '../Button/Button'
import Checkbox from '../Checkbox/Checkbox'
import DatePicker from '../DatePicker/DatePicker'
import Divider from '../Divider/Divider'
import { useForm } from '../hooks/useForm'
import Radio from '../Radio/Radio'
import Select from '../Select/Select'
import TextInput from '../TextInput/TextInput'
import Typography from '../Typography/Typography'

export default {
  title: 'Forms/ReactHookForm',
}

interface ReactHookFormProps {
  resetValues?: DefaultValues<ReactHookFormValues>
}

interface ReactHookFormValues {
  name: string
  birthday: Date | null
  language: string
  title: string
  status: string
  policy: boolean
}

const languages = [
  { value: 'cr', label: 'Cree' },
  { value: 'cs', label: 'Czech' },
  { value: 'da', label: 'Danish' },
  { value: 'de', label: 'German' },
  { value: 'el', label: 'Greek' },
  { value: 'en', label: 'English' },
  { value: 'eo', label: 'Esperanto' },
  { value: 'es', label: 'Spanish' },
  { value: 'et', label: 'Estonian' },
  { value: 'fi', label: 'Finnish' },
  { value: 'fr', label: 'French' },
  { value: 'ga', label: 'Irish' },
  { value: 'he', label: 'Hebrew' },
  { value: 'hi', label: 'Hindi' },
  { value: 'it', label: 'Italian' },
  { value: 'ja', label: 'Japanese' },
  { value: 'ko', label: 'Korean' },
  { value: 'la', label: 'Latin' },
  { value: 'nl', label: 'Dutch' },
  { value: 'pl', label: 'Polish' },
  { value: 'ru', label: 'Russian' },
  { value: 'sv', label: 'Swedish' },
  { value: 'tr', label: 'Turkish' },
  { value: 'uk', label: 'Ukrainian' },
  { value: 'ur', label: 'Urdu' },
  { value: 'uz', label: 'Uzbek' },
  { value: 'vi', label: 'Vietnamese' },
  { value: 'yi', label: 'Yiddish' },
  { value: 'za', label: 'Zhuang' },
  { value: 'zh', label: 'Chinese' },
  { value: 'zh-classical', label: 'Classical Chinese' },
  { value: 'zu', label: 'Zulu' },
]

const defaults = {
  name: 'Jane Doe',
  birthday: new Date(1990, 0, 1),
  language: 'en',
  title: 'miss',
  status: '1',
  policy: true,
}

export function ReactHookForm({
  resetValues,
}: ReactHookFormProps): JSX.Element {
  const methods = useForm<ReactHookFormValues>({
    defaultValues: defaults,
  })

  const onSubmit = methods.handleSubmit((values: ReactHookFormValues) => {
    alert(JSON.stringify(values))
  })

  return (
    <FormProvider {...methods}>
      <form onSubmit={onSubmit}>
        <FormHelper resetValues={resetValues} />
      </form>
    </FormProvider>
  )
}

function FormHelper({ resetValues }: ReactHookFormProps): JSX.Element {
  const { control, register, reset, setValue } = useFormContext()
  const fields: Record<keyof ReactHookFormValues, string> = {
    name: 'Full name',
    birthday: 'Date of birth',
    language: 'Preferred language',
    title: 'Title',
    status: 'Marital status',
    policy: 'Privacy policy',
  }

  const fieldRef = useRef<HTMLInputElement | null>(null)
  const valueRef = useRef<HTMLInputElement | null>(null)

  const registerField = (element: HTMLInputElement) => {
    fieldRef.current = element
  }

  const registerValue = (element: HTMLInputElement) => {
    valueRef.current = element
  }

  return (
    <div className="flex flex-row p-8">
      <div className="flex flex-col p-6 space-y-6">
        <Typography variant="h4">React Hook Form</Typography>
        <Typography variant="body1">
          Select a field and type the value to update the form below. Available
          values are specified in the help text under each field.
          <br />
          Clicking &quot;Reset&quot; button will reset the form to default
          values.
        </Typography>

        {/* react-hook-form controls */}
        <div className="flex items-center space-x-4">
          <Select
            defaultValue=""
            inputRef={registerField}
            label="Field"
            name="field"
          >
            {Object.keys(fields).map((name) => (
              <Select.Option key={`medium-outlined-${name}`} value={name}>
                {fields[name as keyof ReactHookFormValues]}
              </Select.Option>
            ))}
          </Select>
          <TextInput inputRef={registerValue} label="Value" name="value" />
          <Button
            color="primary"
            onClick={() => {
              const name = fieldRef.current?.value as keyof ReactHookFormValues
              let value = valueRef.current?.value as unknown

              if (name === 'birthday') {
                const date = new Date(value as string)
                value = isNaN(date.getTime()) ? null : date
              } else if (value === 'true') {
                value = true
              } else if (value === 'false') {
                value = false
              }

              setValue(name, value ?? '')
            }}
            variant="contained"
          >
            Set
          </Button>
          <Button
            color="primary"
            onClick={() => {
              reset(resetValues)
            }}
            variant="contained"
          >
            Reset
          </Button>
        </div>

        <Divider />

        {/* Form to test */}
        <div className="space-y-6" style={{ width: '30rem' }}>
          <TextInput inputRef={register} label="Full name" name="name" />

          <Controller
            control={control}
            name="birthday"
            render={({ onChange, value }) => (
              <DatePicker
                helperText="Values: any parseable date, e.g. Jan 1, 1990"
                label="Date of birth"
                name="birthday"
                onChange={onChange}
                value={value}
              />
            )}
          />

          <Select
            defaultValue=""
            helperText="Values: en, fr, es, ru, zh, etc."
            inputRef={register}
            label="Preferred language"
            name="language"
          >
            {languages.map(({ label, value }) => (
              <Select.Option key={value} value={value}>
                {label}
              </Select.Option>
            ))}
          </Select>

          <Select
            defaultValue=""
            helperText="Values: mr, mrs, ms, miss"
            inputRef={register}
            label="Title"
            name="title"
          >
            <Select.Option value="mr">Mr.</Select.Option>
            <Select.Option value="mrs">Mrs.</Select.Option>
            <Select.Option value="ms">Ms.</Select.Option>
            <Select.Option value="miss">Miss</Select.Option>
          </Select>

          <Radio.Group
            color="primary"
            defaultValue={1}
            helperText="Values: 1, 2, 3"
            name="status"
            size="medium"
          >
            <Radio.Label>Marital status</Radio.Label>
            <Radio.Input inputRef={register} value={1}>
              Single
            </Radio.Input>
            <Radio.Input inputRef={register} value={2}>
              Married
            </Radio.Input>
            <Radio.Input inputRef={register} value={3}>
              Common law
            </Radio.Input>
          </Radio.Group>

          <Checkbox.Group helperText="Values: true, false">
            <Checkbox.Label>Privacy policy</Checkbox.Label>
            <Checkbox.Input inputRef={register} name="policy" size="medium">
              By using this form you agree to the storage and handling of you
              data by this website
            </Checkbox.Input>
          </Checkbox.Group>

          <Button color="primary" type="submit" variant="contained">
            Submit
          </Button>
        </div>
      </div>
    </div>
  )
}
